INSERT INTO productos (id_producto, id_categoria, id_subcategoria, id_marca, sku, nombre, descripcion_corta, descripcion_larga, precio_actual, precio_anterior, precio_promocional, costo, referencia_proveedor, stock, stock_minimo, garantia_meses, badge, destacado, activo, vistas, ventas_totales, calificacion_promedio, total_resenas, fecha_creacion, fecha_actualizacion) VALUES (162, 2, 32, 15, 'COM-TS-140x190x24', 'Colchón Titanium Special 140x190 (24 cm)', 'Colchón de resortes encapsulados con tecnología Pocket que reduce la transferencia de movimiento. Ofrece una superficie muy suave con telas frescas y un pillow de 5 cm, además de cortes de espuma Convoluted Foam para mayor ventilación y efecto antiestrés【564052701713106†L140-L170】.', 'El Titanium Special de Comodísimos combina elegancia y confort con tecnología avanzada para mejorar la calidad del descanso. Su estructura se basa en un sistema de resortes tipo Pocket que se adapta de forma independiente al cuerpo y reduce la transferencia de movimiento【564052701713106†L140-L170】. La superficie ofrece una firmeza muy suave con un tejido fresco y texturizado, distribuyendo correctamente el peso para mantener la columna en posición ergonómica【564052701713106†L150-L156】. Incluye Convoluted Foam y un pillow de 5 cm, y tecnologías Bioshield® y Ultra-Fresh que eliminan hongos, bacterias y virus【564052701713106†L165-L201】. Las telas 3D Crono y Gaia mejoran la frescura y suavidad, mientras que el Foam Encasement y la zonificación brindan soporte en los bordes y alivian puntos de presión【564052701713106†L178-L220】.', '4145000.00', '4145000.00', '3730000.00', '2487000.00', NULL, 10, 5, 84, 'Oferta', FALSE, TRUE, 0, 0, '0.00', 0, '2025-12-20T20:29:02.197Z', '2025-12-20T20:29:02.197Z');
