INSERT INTO productos (id_producto, id_categoria, id_subcategoria, id_marca, sku, nombre, descripcion_corta, descripcion_larga, precio_actual, precio_anterior, precio_promocional, costo, referencia_proveedor, stock, stock_minimo, garantia_meses, badge, destacado, activo, vistas, ventas_totales, calificacion_promedio, total_resenas, fecha_creacion, fecha_actualizacion) VALUES (165, 2, 32, 15, 'COM-SPS-140x190', 'Colchón Silver Pillow Special 140x190', 'Colchón de resortes Bonell de firmeza intermedia con sistema pillow que brinda confort y soporte. Tiene capas de espuma de alta densidad y tratamiento antiácaros y antibacteriano【599352061822500†L140-L154】.', 'El Silver Pillow Special está diseñado para quienes prefieren un colchón de firmeza media con un sutil confort. Su sistema pillow y la unidad resortada Bonell con soportes en espuma particle foam proporcionan un excelente soporte de peso y evitan deformaciones en el centro【599352061822500†L140-L151】. Incorpora capas de confort de alta densidad y tratamiento antiácaros, hongos y bacterias【599352061822500†L147-L154】. Ofrece opciones de pillow en ambos lados o un solo pillow【599352061822500†L149-L154】 y su acolchado en espuma y tela fresca y transpirable garantiza un descanso cómodo【599352061822500†L152-L154】.', '2405000.00', '2405000.00', '2165000.00', '1443000.00', NULL, 10, 5, 84, 'Oferta', FALSE, TRUE, 0, 0, '0.00', 0, '2025-12-20T20:29:02.197Z', '2025-12-20T20:29:02.197Z');
INSERT INTO productos (id_producto, id_categoria, id_subcategoria, id_marca, sku, nombre, descripcion_corta, descripcion_larga, precio_actual, precio_anterior, precio_promocional, costo, referencia_proveedor, stock, stock_minimo, garantia_meses, badge, destacado, activo, vistas, ventas_totales, calificacion_promedio, total_resenas, fecha_creacion, fecha_actualizacion) VALUES (166, 2, 32, 15, 'COM-GPF-140x190', 'Colchón Gold Pillow Firme 140x190', 'Colchón ortopédico de firmeza confortable con sistema pillow y resortes Bonnell reforzado. Proporciona estabilidad y una postura correcta gracias al refuerzo lumbar y tecnologías Ultra-Fresh y Bioshield®【152086744392812†L140-L159】【152086744392812†L161-L172】.', 'El Gold Pillow Firme brinda un descanso ortopédico y reparador con una superficie firme y cómoda que se adapta a los contornos del cuerpo【152086744392812†L140-L151】. Su sistema de resortes Bonnell incluye un refuerzo en la zona lumbar para gran soporte【152086744392812†L153-L159】. Incorpora tecnologías Ultra-Fresh y Bioshield®【152086744392812†L161-L172】, un pillow de 5 cm y telas 3D Crono y Gaia para frescura y suavidad【152086744392812†L177-L196】, mientras que el Foam Encasement y la zonificación protegen los bordes y alivian puntos de presión【152086744392812†L200-L213】.', '3665000.00', '3665000.00', '3215000.00', '2199000.00', NULL, 10, 5, 84, 'Oferta', FALSE, TRUE, 0, 0, '0.00', 0, '2025-12-20T20:29:02.197Z', '2025-12-20T20:29:02.197Z');
